import java.util.*;

public class Main {
    public static void main(String[] args) {
        DispatchService dispatchService = new DispatchService();
        dispatchService.registerPartner("partner-A", 15); // 15 minutes travel time to this restaurant
        dispatchService.registerPartner("partner-B", 10); // 10 minutes travel time
        dispatchService.registerPartner("partner-C", 30); // 30 minutes travel time, far away

        // Order 1: 12 minutes of prep remaining.
        DispatchResult result1 = dispatchService.dispatch("order-1", 12);
        System.out.println("Order 1 (prep remaining 12 min) dispatched to: " + result1.partnerId + ", waste=" + result1.waste + " min");

        // Order 2: 20 minutes of prep remaining. partner-B is now busy from order 1.
        DispatchResult result2 = dispatchService.dispatch("order-2", 20);
        System.out.println("Order 2 (prep remaining 20 min) dispatched to: " + result2.partnerId + ", waste=" + result2.waste + " min");

        System.out.println("partner-B correctly excluded from order 2 (already busy): " + !result2.partnerId.equals("partner-B"));
    }
}

// The outcome of a dispatch decision: which partner was chosen, and how much
// "waste", the mismatch between their travel time and the food's ready time.
class DispatchResult {
    String partnerId;
    int waste;

    DispatchResult(String partnerId, int waste) {
        this.partnerId = partnerId;
        this.waste = waste;
    }
}

// Chooses, among currently available partners, whichever one's own travel
// time to the restaurant best matches an order's predicted remaining prep
// time, minimizing wasted partner idle time or food cooling time.
class DispatchService {
    private final Map<String, Integer> travelTimeMinutesByPartner = new LinkedHashMap<>(); // partnerId -> ETA to restaurant
    private final Set<String> busyPartners = new HashSet<>();

    void registerPartner(String partnerId, int travelTimeMinutes) {
        travelTimeMinutesByPartner.put(partnerId, travelTimeMinutes);
    }

    DispatchResult dispatch(String orderId, int remainingPrepMinutes) {
        String bestPartnerId = null;
        int bestWaste = Integer.MAX_VALUE;

        for (Map.Entry<String, Integer> entry : travelTimeMinutesByPartner.entrySet()) {
            String partnerId = entry.getKey();
            if (busyPartners.contains(partnerId)) continue; // excluded: already assigned elsewhere

            int travelTime = entry.getValue();
            int waste = Math.abs(travelTime - remainingPrepMinutes); // how far off arrival is from food-ready time
            if (waste < bestWaste) {
                bestWaste = waste;
                bestPartnerId = partnerId;
            }
        }

        busyPartners.add(bestPartnerId); // mark this partner busy, excluding them from future dispatches
        return new DispatchResult(bestPartnerId, bestWaste);
    }
}

