// Chooses, among currently available partners, whichever one's own travel
// time to the restaurant best matches an order's predicted remaining prep
// time, minimizing wasted partner idle time or food cooling time.
class DispatchService {
public:
    void registerPartner(const string& partnerId, int travelTimeMinutes) {
        travelTimeMinutesByPartner[partnerId] = travelTimeMinutes;
        partnerOrder.push_back(partnerId); // preserve registration order for deterministic iteration
    }

    DispatchResult dispatch(const string& orderId, int remainingPrepMinutes) {
        string bestPartnerId = "";
        int bestWaste = INT_MAX;

        for (const auto& partnerId : partnerOrder) {
            if (busyPartners.count(partnerId)) continue; // excluded: already assigned elsewhere

            int travelTime = travelTimeMinutesByPartner[partnerId];
            int waste = abs(travelTime - remainingPrepMinutes); // how far off arrival is from food-ready time
            if (waste < bestWaste) {
                bestWaste = waste;
                bestPartnerId = partnerId;
            }
        }

        busyPartners.insert(bestPartnerId); // mark this partner busy, excluding them from future dispatches
        return {bestPartnerId, bestWaste};
    }

private:
    map<string, int> travelTimeMinutesByPartner; // partnerId -> ETA to restaurant
    vector<string> partnerOrder;
    set<string> busyPartners;
};

int main() {
    DispatchService dispatchService;
    dispatchService.registerPartner("partner-A", 15); // 15 minutes travel time to this restaurant
    dispatchService.registerPartner("partner-B", 10); // 10 minutes travel time
    dispatchService.registerPartner("partner-C", 30); // 30 minutes travel time, far away

    // Order 1: 12 minutes of prep remaining.
    DispatchResult result1 = dispatchService.dispatch("order-1", 12);
    cout << "Order 1 (prep remaining 12 min) dispatched to: " << result1.partnerId << ", waste=" << result1.waste << " min" << endl;

    // Order 2: 20 minutes of prep remaining. partner-B is now busy from order 1.
    DispatchResult result2 = dispatchService.dispatch("order-2", 20);
    cout << "Order 2 (prep remaining 20 min) dispatched to: " << result2.partnerId << ", waste=" << result2.waste << " min" << endl;

    cout << "partner-B correctly excluded from order 2 (already busy): " << (result2.partnerId != "partner-B" ? "true" : "false") << endl;

    return 0;
}

